import React, { useEffect, useState } from "react";
import MainNav from "../MainNav/MainNav";
import axios from "axios";

const URL = "http://localhost:5000/artists";

const fetchHandler = async () => {
  return await axios.get(URL).then((res) => res.data);
};

function Artists() {
  const [artists, setArtists] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchHandler()
      .then((data) => {
        // data is expected to be an array directly
        setArtists(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch(() => {
        setError("Failed to fetch artists");
        setLoading(false);
      });
  }, []);

  if (loading) return <h2>Loading artists...</h2>;
  if (error) return <h2 style={{ color: "red" }}>{error}</h2>;

  return (
    <div>
      <MainNav />
      <h1>Artist Details Display Page</h1>

      {artists.length === 0 ? (
        <p>No artists found.</p>
      ) : (
        artists.map((artist, i) => (
          <div
            key={i}
            style={{
              border: "1px solid gray",
              padding: "10px",
              marginBottom: "10px",
              borderRadius: "5px",
            }}
          >
            <h2>{artist.artistName}</h2>
            <p>
              <strong>ID:</strong> {artist._id || artist.artist_id}
            </p>
            <p>
              <strong>Genre:</strong> {artist.genre}
            </p>
            <p>
              <strong>Category:</strong> {artist.category}
            </p>
            <p>
              <strong>Booking Price:</strong> {artist.bookingPrice}
            </p>
            <p>
              <strong>Summary:</strong> {artist.summary}
            </p>
            <p>
              <strong>Bio:</strong> {artist.bio}
            </p>
            {artist.image && (
              <img
                src={`http://localhost:5000/uploads/${artist.image}`}
                alt={artist.artistName}
                style={{ width: "150px", height: "150px", objectFit: "cover" }}
              />
            )}
          </div>
        ))
      )}
    </div>
  );
}

export default Artists;
